properties.query:
let InstallThreshold = 10;
// Who and where ride on the threat's alert.raised (the same ThreatId).
let WhoAndWhere = AIBPEvents_CL
| where EventType == "alert.raised"
| summarize arg_max(TimeGenerated, Affected, AffectedMachines) by ThreatId;
AIBPEvents_CL
// Arrival time, not event time: events land minutes after they happen.
// The 1d query period lets rows that arrive late after an outage count.
| where ingestion_time() > ago(1h)
// A detection carries the count when found; a later alert carries it
// again, so an extension that spreads after detection still fires.
| where EventType == "threat.detected" or (EventType == "alert.raised" and IssueKind == "malicious")
| where InstallCount >= InstallThreshold
| summarize arg_max(InstallCount, *) by ExtensionId
| join kind=leftouter (WhoAndWhere | project ThreatId, Affected1 = Affected, AffectedMachines1 = AffectedMachines) on ThreatId
| extend Affected = iif(isnull(Affected) or array_length(Affected) == 0, Affected1, Affected)
| extend AffectedMachines = iif(isnull(AffectedMachines), AffectedMachines1, AffectedMachines)
| extend MalwareName = iif(isnotempty(ExtensionName), ExtensionName, ExtensionId), FlaggedReason = tostring(Data.threats[0].flaggedReason)
// The first two machines and their users, as Host and Account entities
// (a rule maps at most five entities; the extension is the fifth).
| extend Host1 = tostring(Affected[0].machineName), Host2 = tostring(Affected[1].machineName)
| extend User1 = tostring(Affected[0].userEmail), User2 = tostring(Affected[1].userEmail)
| project TimeGenerated, EventId, ThreatId, ExtensionId, ExtensionName, MalwareName, Severity, InstallCount, AffectedMachines, FlaggedReason, DashboardUrl, Host1, Host2, User1, User2
